-- The MCP paragraph names the editor preset. Each UPDATE only changes text that is still present, so the migration is safe to rerun.
SET NAMES utf8mb4;

UPDATE cms_articles SET bodytext = REPLACE(bodytext, 'The key form offers presets for such a key (Agent for content, Agent drafts only, Read only), and after the key is issued the page shows the client configuration with the key once.', 'The key form offers presets for such a key (Editor with structure and statistics, Agent for content, Agent drafts only, Read only), and after the key is issued the page shows the client configuration with the key once. The editor preset also lets the assistant manage pages, the menu, boxes and images and read statistics, and the assistant explains how the site works to an editor who is not technical.') WHERE LOCATE('The key form offers presets for such a key (Agent for content, Agent drafts only, Read only), and after the key is issued the page shows the client configuration with the key once.', bodytext) > 0 AND LOCATE('Editor with structure and statistics', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = REPLACE(bodytext, 'Formulář klíče nabízí předvolby pro takový klíč (Agent pro obsah, Agent jen koncepty, Jen čtení) a po vydání klíče stránka jednou ukáže konfiguraci klienta s klíčem.', 'Formulář klíče nabízí předvolby pro takový klíč (Redaktor se strukturou a statistikami, Agent pro obsah, Agent jen koncepty, Jen čtení) a po vydání klíče stránka jednou ukáže konfiguraci klienta s klíčem. Předvolba pro redaktora dovolí asistentovi také spravovat stránky, menu, boxy a obrázky a číst statistiky a asistent redaktorovi, který nerozumí technice, vysvětlí, jak web funguje.') WHERE LOCATE('Formulář klíče nabízí předvolby pro takový klíč (Agent pro obsah, Agent jen koncepty, Jen čtení) a po vydání klíče stránka jednou ukáže konfiguraci klienta s klíčem.', bodytext) > 0 AND LOCATE('Redaktor se strukturou a statistikami', bodytext) = 0;
